def encode(message):
    """
    Encodes a message by swapping the case of all letters and replacing
    vowels with the letter that appears 2 places ahead in the alphabet.

    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'AEIOUaeiou'
    vowel_map = {
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W',
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w'
    }
    result = []
    for char in message:
        if char in vowels:
            # Replace vowel with the letter 2 places ahead
            new_char = vowel_map[char]
            # Swap the case
            if new_char.isupper():
                result.append(new_char.lower())
            else:
                result.append(new_char.upper())
        else:
            # Swap the case of non-vowel characters
            if char.isupper():
                result.append(char.lower())
            else:
                result.append(char.upper())
    return ''.join(result)

