import heapq
def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue elements: (path_tuple, row, col)
    heap = []
    for i in range(N):
        for j in range(N):
            initial_path = (grid[i][j],)
            heapq.heappush(heap, (initial_path, i, j))

    while heap:
        path, row, col = heapq.heappop(heap)
        if len(path) == k:
            return list(path)
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < N and 0 <= new_col < N:
                new_path = path + (grid[new_row][new_col],)
                heapq.heappush(heap, (new_path, new_row, new_col))

    return []

